package com.jobportal.repository;
import com.jobportal.entity.Job; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface JobRepository extends JpaRepository<Job,Long>{ List<Job> findByActiveTrueAndApprovalStatusOrderByPostedAtDesc(Job.ApprovalStatus status); List<Job> findByRecruiterIdOrderByPostedAtDesc(Long id);
 List<Job> findByApprovalStatusOrderByPostedAtDesc(Job.ApprovalStatus status); @Query("select j from Job j where j.active=true and j.approvalStatus=com.jobportal.entity.Job.ApprovalStatus.APPROVED and (:q is null or :q='' or lower(j.title) like lower(concat('%',:q,'%')) or lower(j.company) like lower(concat('%',:q,'%')) or lower(j.location) like lower(concat('%',:q,'%'))) and (:company is null or :company='' or lower(j.company) like lower(concat('%',:company,'%'))) and (:location is null or :location='' or lower(j.location) like lower(concat('%',:location,'%'))) order by j.postedAt desc") List<Job> search(@Param("q") String q,@Param("company") String company,@Param("location") String location); long countByActiveTrue(); long countByActiveTrueAndApprovalStatus(Job.ApprovalStatus status); }
